import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { defineConfig, type DefaultTheme, type HeadConfig } from "vitepress";
import { withMermaid } from "vitepress-plugin-mermaid";

// The platform documentation sidebar is generated by
// scripts/sync-platform-docs.mjs (run in CI before the build; run it locally
// against a platform checkout to preview the synced docs). Absent means the
// sync has not run - the site still builds, without the platform section.
const platformSidebarPath = fileURLToPath(
  new URL("./generated/platform-sidebar.json", import.meta.url),
);
const platformSidebar: DefaultTheme.SidebarItem[] = existsSync(platformSidebarPath)
  ? JSON.parse(readFileSync(platformSidebarPath, "utf8"))
  : [];
const platformDocsSynced = platformSidebar.length > 0;
const apiReferenceSynced = existsSync(
  fileURLToPath(new URL("../public/api/index.html", import.meta.url)),
);
// Same pattern for the plugin documentation (scripts/sync-plugin-docs.mjs):
// the step-plugin repository owns those pages; absent means unsynced.
const pluginSidebarPath = fileURLToPath(
  new URL("./generated/plugin-docs-sidebar.json", import.meta.url),
);
const pluginSidebar: DefaultTheme.SidebarItem[] = existsSync(pluginSidebarPath)
  ? JSON.parse(readFileSync(pluginSidebarPath, "utf8"))
  : [];
const pluginDocsSynced = pluginSidebar.length > 0;

const siteTitle = "Hegemony";
const browserTitle = "Hegemony.sh";
const siteUrl = "https://hegemony.sh";
const githubRepoUrl = "https://github.com/hegemony-sh/hegemony";
const descriptionEn =
  "A proof-of-execution platform for deterministic, long-running infrastructure workflows on Temporal.";
const descriptionCs =
  "Platforma proof-of-execution pro deterministická, dlouhotrvající infrastrukturní workflow postavená na Temporal.";

// A page's public URL path from its source path: "cs/docs/index.md" ->
// "/cs/docs/", "features.md" -> "/features" (cleanUrls).
function pagePath(relativePath: string): string {
  return `/${relativePath}`.replace(/(^|\/)index\.md$/, "$1").replace(/\.md$/, "");
}

function sourceExists(relativePath: string): boolean {
  return existsSync(fileURLToPath(new URL(`../${relativePath}`, import.meta.url)));
}

// https://vitepress.dev/reference/site-config
export default withMermaid(
  defineConfig({
    srcExclude: ["README.md", "test-results/**", ".platform/**", ".plugins/**"],
    // /docs/platform/ pages exist only after the sync script has run; the
    // built-HTML link check in CI verifies them strictly there.
    ignoreDeadLinks: [
      /^\/docs\/platform\//,
      /^\/docs\/plugins\//,
      // Example/default URLs in the synced reference pages (settings defaults
      // like the local Keycloak issuer) are illustrations, not links to check.
      /^https?:\/\/(localhost|127\.0\.0\.1)/,
    ],

    // mermaid lazy-loads its diagram renderers, so the dev server's dependency
    // scan misses their CommonJS imports (fastdom in particular has no ESM
    // default export until Vite pre-bundles it, which breaks every page in dev
    // mode and the e2e suite with it). Force both through optimization;
    // withMermaid appends its own additions to this list. Production builds
    // are unaffected either way (rollup does CJS interop itself).
    vite: {
      optimizeDeps: {
        include: ["mermaid", "fastdom"],
      },
      // Build-time flags for pages that link into the synced trees (the
      // docs index "Where to go" tip): those links render only when the
      // artifacts actually exist in this build, so an unsynced build
      // publishes no dead references.
      define: {
        __PLATFORM_DOCS_SYNCED__: JSON.stringify(platformDocsSynced),
        __API_REFERENCE_SYNCED__: JSON.stringify(apiReferenceSynced),
        __PLUGIN_DOCS_SYNCED__: JSON.stringify(pluginDocsSynced),
      },
    },

    markdown: {
      anchor: {
        // GitHub's slug algorithm, so anchors written against GitHub rendering
        // (the platform docs' native habitat, verified by its link gate) hit
        // the same ids here: "Flow / Flow Definition" -> #flow--flow-definition.
        slugify: (value: string) =>
          value
            .normalize("NFKD")
            .replace(/[\u0300-\u036f]/g, "")
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9 _-]/g, "")
            .replace(/ /g, "-"),
      },
      config(md) {
        // The platform docs show template syntax ({{ vars.X }}) in inline code
        // spans. VitePress v-pres fenced code automatically but not inline
        // code, so Vue would parse those mustaches as interpolations and fail
        // the build; mark every inline code span v-pre.
        const defaultRender =
          md.renderer.rules.code_inline ??
          ((tokens, idx, options, _env, self) => self.renderToken(tokens, idx, options));
        md.renderer.rules.code_inline = (tokens, idx, options, env, self) => {
          tokens[idx].attrSet("v-pre", "");
          return defaultRender(tokens, idx, options, env, self);
        };
      },
    },
    title: browserTitle,
    titleTemplate: ":title - Hegemony.sh",
    description: descriptionEn,
    lang: "en-US",
    cleanUrls: true,
    appearance: "dark",

    // sitemap.xml for search engines; public/robots.txt points at it.
    sitemap: { hostname: siteUrl },

    // Per-page head tags: the canonical URL, the link-preview (Open Graph)
    // tags in the page's own language, and - for a page that exists in both
    // languages - the alternate-language links that tell a search engine the
    // two are one page. The synced platform and plugin docs are English
    // only, so they get no alternates.
    transformHead({ pageData, title, description }) {
      if (pageData.isNotFound) return [];
      const relativePath = pageData.relativePath;
      const isCzech = relativePath.startsWith("cs/");
      const url = siteUrl + pagePath(relativePath);
      const tags: HeadConfig[] = [
        ["link", { rel: "canonical", href: url }],
        ["meta", { property: "og:title", content: title }],
        ["meta", { property: "og:description", content: description }],
        ["meta", { property: "og:url", content: url }],
        ["meta", { property: "og:locale", content: isCzech ? "cs_CZ" : "en_US" }],
      ];
      const englishSource = isCzech ? relativePath.slice(3) : relativePath;
      const czechSource = `cs/${englishSource}`;
      if (sourceExists(englishSource) && sourceExists(czechSource)) {
        const english = siteUrl + pagePath(englishSource);
        const czech = siteUrl + pagePath(czechSource);
        tags.push(
          ["link", { rel: "alternate", hreflang: "en", href: english }],
          ["link", { rel: "alternate", hreflang: "cs", href: czech }],
          ["link", { rel: "alternate", hreflang: "x-default", href: english }],
        );
      }
      return tags;
    },

    head: [
      ["link", { rel: "icon", href: "/favicon.ico", sizes: "any" }],
      ["link", { rel: "icon", type: "image/png", sizes: "32x32", href: "/brand/favicon-32.png" }],
      ["link", { rel: "icon", type: "image/png", sizes: "16x16", href: "/brand/favicon-16.png" }],
      ["link", { rel: "apple-touch-icon", href: "/brand/apple-touch-icon.png" }],
      ["link", { rel: "manifest", href: "/site.webmanifest" }],
      ["meta", { name: "theme-color", content: "#131313" }],
      ["meta", { property: "og:type", content: "website" }],
      ["meta", { property: "og:site_name", content: browserTitle }],
      ["meta", { property: "og:image", content: `${siteUrl}/brand/logo-stacked@2x.png` }],
    ],

    themeConfig: {
      logo: "/brand/favicon-48.png",
      siteTitle,
      socialLinks: [{ icon: "github", link: githubRepoUrl, ariaLabel: "GitHub" }],

      search: {
        provider: "local",
        options: {
          locales: {
            cs: {
              translations: {
                button: {
                  buttonText: "Hledat",
                  buttonAriaLabel: "Otevřít vyhledávání",
                },
                modal: {
                  displayDetails: "Zobrazit podrobný seznam",
                  resetButtonTitle: "Vymazat hledání",
                  backButtonTitle: "Zavřít vyhledávání",
                  noResultsText: "Nenalezeny žádné výsledky pro",
                  footer: {
                    selectText: "pro výběr",
                    selectKeyAriaLabel: "Enter",
                    navigateText: "pro pohyb",
                    navigateUpKeyAriaLabel: "šipka nahoru",
                    navigateDownKeyAriaLabel: "šipka dolů",
                    closeText: "pro zavření",
                    closeKeyAriaLabel: "Escape",
                  },
                },
              },
            },
          },
        },
      },
    },

    locales: {
      root: {
        label: "English",
        lang: "en-US",
        title: browserTitle,
        description: descriptionEn,
        themeConfig: {
          nav: [
            { text: "Home", link: "/" },
            { text: "Features", link: "/features" },
            { text: "Docs", link: "/docs/" },
            // Served from public/api/ only after the sync has run.
            ...(apiReferenceSynced
              ? [{ text: "API Reference", link: "/api/", target: "_self" }]
              : []),
          ],
          sidebar: {
            "/docs/": [
              {
                text: "Getting Started",
                items: [{ text: "Introduction", link: "/docs/" }],
              },
              ...(platformSidebar.length > 0
                ? [
                    {
                      text: "Platform Documentation",
                      items: [{ text: "Browse the platform docs", link: "/docs/platform/" }],
                    },
                  ]
                : []),
              ...(pluginDocsSynced
                ? [
                    {
                      text: "Step Plugins",
                      items: [{ text: "Browse the plugin docs", link: "/docs/plugins/" }],
                    },
                  ]
                : []),
            ],
            "/docs/platform/": platformSidebar,
            "/docs/plugins/": pluginSidebar,
          },
          langMenuLabel: "Languages",
          footer: {
            message:
              'Released as open source under the AGPL-3.0-or-later license. Development is sponsored by <a href="https://rexonix.cz/" target="_blank" rel="noreferrer">Rexonix s.r.o.</a> Contact — <a href="mailto:contact@hegemony.sh">contact@hegemony.sh</a>.',
            copyright: "Copyright © 2025–2026 Rexonix s.r.o. Written by Jakub Trávník.",
          },
        },
      },
      cs: {
        label: "Čeština",
        lang: "cs-CZ",
        link: "/cs/",
        title: browserTitle,
        description: descriptionCs,
        themeConfig: {
          nav: [
            { text: "Úvod", link: "/cs/" },
            { text: "Funkce", link: "/cs/features" },
            { text: "Dokumentace", link: "/cs/docs/" },
            // The API reference exists only in English; say so in the label.
            ...(apiReferenceSynced
              ? [{ text: "API reference (anglicky)", link: "/api/", target: "_self" }]
              : []),
          ],
          sidebar: {
            "/cs/docs/": [
              {
                text: "První kroky",
                items: [{ text: "Úvod", link: "/cs/docs/" }],
              },
              // The synced documentation sections are English-only; the
              // labels say so, and the links lead straight to the English
              // pages rather than to nonexistent /cs/ alternates.
              ...(platformDocsSynced
                ? [
                    {
                      text: "Dokumentace platformy (anglicky)",
                      items: [{ text: "Procházet dokumentaci platformy", link: "/docs/platform/" }],
                    },
                  ]
                : []),
              ...(pluginDocsSynced
                ? [
                    {
                      text: "Pluginy kroků (anglicky)",
                      items: [{ text: "Procházet dokumentaci pluginů", link: "/docs/plugins/" }],
                    },
                  ]
                : []),
            ],
          },
          langMenuLabel: "Jazyky",
          footer: {
            message:
              'Open source projekt pod licencí AGPL-3.0-or-later. Vývoj projektu finančně podporuje <a href="https://rexonix.cz/" target="_blank" rel="noreferrer">Rexonix s.r.o.</a> Kontakt — <a href="mailto:contact@hegemony.sh">contact@hegemony.sh</a>.',
            copyright: "Copyright © 2025–2026 Rexonix s.r.o. Autor: Jakub Trávník.",
          },
        },
      },
    },
  }),
);
